# Numerical counterparts of tables typed directly into the manuscript appendix.
source(here::here('replication','R','helpers.R'))
tab <- file.path(v2_root,'generated_tables')
emit <- function(z,name,digits=3) {
 write_csv(z,file.path(v2_out,paste0(name,'.csv')))
 f <- z |> mutate(across(where(is.numeric),~ifelse(is.na(.x),'--',formatC(.x,format='f',digits=digits))))
 writeLines(apply(as.data.frame(f),1,function(r) paste0(paste(r,collapse=' & '),' \\')),file.path(tab,paste0(name,'_rows.tex')))
}
z <- read_csv(here::here('data','inputs','auction_audit_decisions.csv'),show_col_types=FALSE)
weighted <- z |> group_by(commodity,source_group) |> summarise(frame_N=sum(sampling_weight),estimated_error_total=sum(sampling_weight*definite_error),weighted_error_rate=sum(sampling_weight*definite_error)/sum(sampling_weight),sample_n=n(),disagreements=sum(definite_error),.groups='drop')
strata <- z |> group_by(commodity,source_group,stratum) |> summarise(N=first(stratum_N),n=n(),e=sum(definite_error),.groups='drop') |> group_by(commodity,source_group) |> mutate(H=n()) |> ungroup()
bounds <- pmap_dfr(strata,function(commodity,source_group,stratum,N,n,e,H) {
 M <- seq.int(e,N-n+e);alpha <- .05/H
 lower_tail <- phyper(e,M,N-M,n)
 upper_tail <- if(e==0) rep(1,length(M)) else phyper(e-1,M,N-M,n,lower.tail=FALSE)
 tibble(commodity,source_group,stratum,N,n,e,lower_total=min(M[upper_tail>=alpha/2]),upper_total=max(M[lower_tail>=alpha/2]))
})
write_csv(bounds,file.path(v2_out,'auction_audit_stratum_bounds.csv'))
domain <- bounds |> group_by(commodity,source_group) |> summarise(frame_N=sum(N),lower95=sum(lower_total)/sum(N),upper95=sum(upper_total)/sum(N),.groups='drop')
emit(left_join(weighted,domain,by=c('commodity','source_group','frame_N')),'appendix_xml_audit')
emit(v2_read('source_connectivity_summary.csv'),'appendix_connectivity',0)
emit(v2_read('state_model_parameters.csv'),'appendix_parameters')
emit(v2_read('model_numerical_checks.csv'),'appendix_numerical_checks',8)
emit(v2_read('variant_neutral_start_checks.csv'),'appendix_variant_numerical_checks',8)
emit(v2_read('pass_through_1820s_summary.csv'),'appendix_pass_through')
vp <- v2_read('structural_variant_parameters.csv') |> left_join(v2_read('structural_variant_comparison.csv'),by='variant_id')
emit(vp |> select(variant_id,channels,channel_years,common_sd,relative_sd,wheat_transitory_sd,auction_observation_sd,official_observation_sd,other_observation_sd,negative_log_likelihood,max_index_difference_pct,max_inflation_difference_pp,mean1820s),'appendix_variant_parameters')
emit(v2_read('equipment_allocation_variants.csv') |> filter(year%in%c(1700,1787,1795,1800,1818,1822,1834)) |> select(equipment_share,method,year,index) |> pivot_wider(names_from=year,values_from=index),'appendix_equipment_allocations',1)
emit(v2_read('partial_market_reference_weights.csv'),'appendix_market_weights',4)
emit(v2_read('published_basket_accounting_comparison.csv') |> filter(year%in%c(1700,1743,1769,1770,1794,1795,1800,1818,1820,1821,1822,1834)),'appendix_published_comparison',3)
emit(v2_read('enslaved_recorded_characteristics_decadal_companion.csv') |> select(decade,years,adjusted_index,lower_95,upper_95,raw_geometric_index,consumption_index,recorded_characteristics_adjusted_relative_index),'appendix_enslaved_decades',1)
assets <- read_csv(here::here('data','inputs','excluded_asset_annual_counts.csv'),show_col_types=FALSE) |> group_by(category) |> summarise(lots=sum(lots),observed_years=n_distinct(year),first_year=min(year),last_year=max(year),.groups='drop')
emit(assets,'appendix_excluded_assets',0)
emit(v2_read('nominal_exclusion_counts.csv'),'appendix_exclusions',0)
write_csv(read_csv(here::here('data','inputs','historical_events.csv'),show_col_types=FALSE),file.path(v2_out,'appendix_historical_events.csv'))
